module divide_clock_by_4_SV (   input logic clk, rst_b,   output logic y);   typedef enum bit [3:0] {s0 = 4'b0001, s1 = 4'b0010, s2 = 4'b0100, s3 = 4'b1000} state_type_t;   state_type_t [3:0] state, next_state;// Output   assign y_out = (state == s3);// State transitions   always_ff @ (posedge clk, negedge rst_b)       if (!rst_b) state <= s0; else state <= next_state;   always_comb @ ( state)	 // Next state logic      case (state)         s0: next_state = s1;         s1: next_state = s2;         s2: next_state = s3;         s3: next_state = s0;	// case is complete Ð no default       endcaseendmodule